import re

from .errors import ValidationError
from .money import parse_money
from .splits import split_equal, split_exact, split_percent


def load_group(data):
    """Return the normalized members and an iterator over validated expenses."""
    if not isinstance(data, dict):
        raise ValidationError("group must be an object")

    currency = data.get("currency")
    if not isinstance(currency, str) or re.fullmatch(r"[A-Za-z]{3}", currency) is None:
        raise ValidationError("currency must be a three-letter code")

    raw_members = data.get("members")
    if not isinstance(raw_members, list) or not raw_members:
        raise ValidationError("members must be a non-empty list")
    members = [_normalize_name(name) for name in raw_members]
    member_names = set(members)
    if len(member_names) != len(members):
        raise ValidationError("duplicate member name")

    raw_expenses = data.get("expenses")
    if not isinstance(raw_expenses, list):
        raise ValidationError("expenses must be a list")
    return members, _iter_expenses(raw_expenses, member_names)


def _iter_expenses(raw_expenses, member_names):
    seen_ids = set()
    for expense in raw_expenses:
        if not isinstance(expense, dict):
            raise ValidationError("each expense must be an object with a string id")
        expense_id = expense.get("id")
        if not isinstance(expense_id, str):
            raise ValidationError("expense id must be a string")
        if expense_id in seen_ids:
            raise ValidationError(f"duplicate expense id {expense_id}")
        seen_ids.add(expense_id)

        try:
            payer = _normalize_name(expense.get("payer"))
            if payer not in member_names:
                raise ValidationError(f"unknown payer {payer!r}")
            amount = parse_money(expense.get("amount"))
            if amount == 0:
                raise ValidationError("expense amount must be greater than zero")
            shares = _load_shares(expense.get("split"), amount, member_names)
        except ValidationError as exc:
            raise ValidationError(f"expense {expense_id}: {exc}") from exc
        yield {"payer": payer, "amount": amount, "shares": shares}


def _normalize_name(value):
    if isinstance(value, str):
        name = value.strip().lower()
        if name:
            return name
    raise ValidationError("name must be a non-empty string")


def _load_shares(split, amount, members):
    if not isinstance(split, dict):
        raise ValidationError("split must be an object")
    kind = split.get("type")
    if not isinstance(kind, str):
        raise ValidationError("split type must be a string")
    if kind == "equal":
        if "among" not in split:
            return split_equal(amount, members)
        among = split["among"]
        if not isinstance(among, list) or not among:
            raise ValidationError("among must be a non-empty list")
        return split_equal(amount, _normalize_participants(among, members))
    if kind == "exact":
        return split_exact(amount, _load_split_values(split, "amounts", members))
    if kind == "percent":
        return split_percent(amount, _load_split_values(split, "percents", members))
    raise ValidationError(f"unknown split type {kind!r}")


def _normalize_participants(names, members):
    participants = []
    seen = set()
    for value in names:
        name = _normalize_name(value)
        if name not in members:
            raise ValidationError(f"unknown split participant {name!r}")
        if name in seen:
            raise ValidationError(f"duplicate split participant {name!r}")
        seen.add(name)
        participants.append(name)
    return participants


def _load_split_values(split, field, members):
    values = split.get(field)
    if not isinstance(values, dict):
        raise ValidationError(f"{field} must be an object")
    names = _normalize_participants(values, members)
    return dict(zip(names, values.values()))
import re

from .errors import ValidationError


_HUNDREDTHS = re.compile(r"([0-9]+)(?:\.([0-9]{1,2}))?")
_CHUNK_DIGITS = 18
_CHUNK_BASE = 10 ** _CHUNK_DIGITS


def _parse_hundredths(value, label):
    if not isinstance(value, str):
        raise ValidationError(f"{label} must be a string")
    match = _HUNDREDTHS.fullmatch(value)
    if match is None:
        raise ValidationError(f"invalid {label} {value!r}")
    whole, fraction = match.groups()
    # Parse in chunks so valid amounts are independent of Python's digit limit.
    units = 0
    for start in range(0, len(whole), _CHUNK_DIGITS):
        chunk = whole[start : start + _CHUNK_DIGITS]
        units = units * 10 ** len(chunk) + int(chunk)
    return units * 100 + int((fraction or "").ljust(2, "0"))


def parse_money(value):
    """Turn a money string such as "12.50" into cents."""
    return _parse_hundredths(value, "money value")


def parse_percent(value):
    """Turn a percentage string into hundredths of a percent."""
    result = _parse_hundredths(value, "percentage")
    if result == 0:
        raise ValidationError("percentages must be greater than zero")
    return result


def format_money(cents):
    whole, fraction = divmod(abs(cents), 100)
    chunks = []
    while whole >= _CHUNK_BASE:
        whole, chunk = divmod(whole, _CHUNK_BASE)
        chunks.append(f"{chunk:0{_CHUNK_DIGITS}d}")
    sign = "-" if cents < 0 else ""
    return f"{sign}{whole}{''.join(reversed(chunks))}.{fraction:02d}"
from .errors import ValidationError
from .money import parse_money, parse_percent


def split_equal(amount, among):
    return _split_weighted(amount, dict.fromkeys(among, 1), len(among))


def split_exact(amount, amounts):
    shares = {name: parse_money(value) for name, value in amounts.items()}
    if sum(shares.values()) != amount:
        raise ValidationError("exact shares must add up to the expense amount")
    return shares


def split_percent(amount, percents):
    weights = {name: parse_percent(value) for name, value in percents.items()}
    if sum(weights.values()) != 10_000:
        raise ValidationError("percentages must add up to 100")
    return _split_weighted(amount, weights, 10_000)


def _split_weighted(amount, weights, total_weight):
    shares = {}
    remainders = {}
    for name, weight in weights.items():
        shares[name], remainders[name] = divmod(amount * weight, total_weight)

    leftover = amount - sum(shares.values())
    if leftover:
        ranked = sorted(remainders, key=lambda name: (-remainders[name], name))
        for name in ranked[:leftover]:
            shares[name] += 1
    return shares
import json
import sys

from .core import balances, settle
from .errors import ValidationError
from .money import format_money


_JSON_NUMBER = object()


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    if len(argv) != 2:
        print("usage: python3 -m ledger {balances,settle} GROUP.json", file=sys.stderr)
        return 1
    command, path = argv
    if command not in ("balances", "settle"):
        print(f"unknown command {command!r}", file=sys.stderr)
        return 1

    try:
        with open(path, "rb") as f:
            group = json.load(
                f,
                parse_int=_json_number,
                parse_float=_json_number,
                parse_constant=_reject_json_constant,
            )
    except (OSError, ValueError, RecursionError) as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 1

    try:
        if command == "balances":
            for name, cents in sorted(balances(group).items()):
                sign = "+" if cents > 0 else ""
                print(f"{name}: {sign}{format_money(cents)}")
        else:
            transfers = settle(group)
            if not transfers:
                print("all settled")
            for frm, to, cents in transfers:
                print(f"{frm} -> {to}: {format_money(cents)}")
    except ValidationError as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 2
    return 0


def _json_number(_literal):
    # Numeric tokens fail schema validation regardless of their magnitude.
    return _JSON_NUMBER


def _reject_json_constant(value):
    raise ValueError(f"invalid JSON constant {value!r}")
